package edu.facilities.ui; import edu.facilities.model.*; import edu.facilities.service.*; import javafx.fxml.*; import javafx.collections.*; import javafx.scene.control.*; import java.sql.*;
public class StudentCourseCatalogController { @FXML private TableView<Course> coursesTable; @FXML private TableColumn<Course,String> codeColumn,nameColumn,typeColumn; @FXML private TableColumn<Course,Integer> creditsColumn,seatsColumn; @FXML private TextField searchField; @FXML private ComboBox<String> departmentFilter,typeFilter; @FXML private Label messageLabel; @FXML public void initialize(){codeColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getCode()));nameColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getName()));typeColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getType().name()));creditsColumn.setCellValueFactory(x->new javafx.beans.property.SimpleIntegerProperty(x.getValue().getCredits()).asObject());seatsColumn.setCellValueFactory(x->new javafx.beans.property.SimpleIntegerProperty(x.getValue().getAvailableSeats()).asObject());try{departmentFilter.getItems().add("ALL");departmentFilter.getItems().addAll(new CourseService().getAllDepartments());}catch(SQLException e){messageLabel.setText(e.getMessage());}typeFilter.getItems().addAll("ALL","CORE","ELECTIVE");departmentFilter.setValue("ALL");typeFilter.setValue("ALL");load();} @FXML private void search(){load();} @FXML private void reset(){searchField.clear();departmentFilter.setValue("ALL");typeFilter.setValue("ALL");load();} private void load(){try{var q=searchField.getText().trim();var d="ALL".equals(departmentFilter.getValue())?null:departmentFilter.getValue();var t="ALL".equals(typeFilter.getValue())?null:CourseType.valueOf(typeFilter.getValue());var courses=q.isBlank()?new CourseService().filter(d,null,t,true):new CourseService().search(q);coursesTable.setItems(FXCollections.observableArrayList(courses));messageLabel.setText(coursesTable.getItems().size()+" course(s)");}catch(SQLException e){messageLabel.setText(e.getMessage());}} @FXML private void enroll(){var c=coursesTable.getSelectionModel().getSelectedItem();try{if(c==null)throw new IllegalArgumentException("Select a course.");new EnrollmentService().enrollStudent(AuthService.getInstance().getCurrentUser(),c);messageLabel.setText("CORE enrollment successful.");load();}catch(Exception e){messageLabel.setText(e.getMessage());}}}
